* TRAF1 -- Traffic log screen
MAP TRAF1 SIZE 24x80
  FIELD HEADER    AT 0,2   LEN 40 PROT BRIGHT COLOR=WHITE
  FIELD USERID    AT 0,70  LEN 8  PROT DIM    COLOR=TURQUOISE
  FIELD LOGDATE   AT 2,20  LEN 8  UNPROT BRIGHT COLOR=WHITE
  FIELD SHOWID    AT 2,35  LEN 8  UNPROT BRIGHT COLOR=TURQUOISE
  FIELD L1TIME    AT 5,5   LEN 5  PROT DIM    COLOR=TURQUOISE
  FIELD L1TYPE    AT 5,12  LEN 4  PROT BRIGHT COLOR=YELLOW
  FIELD L1TITLE   AT 5,18  LEN 30 PROT BRIGHT COLOR=WHITE
  FIELD L2TIME    AT 7,5   LEN 5  PROT DIM    COLOR=TURQUOISE
  FIELD L2TYPE    AT 7,12  LEN 4  PROT BRIGHT COLOR=YELLOW
  FIELD L2TITLE   AT 7,18  LEN 30 PROT BRIGHT COLOR=WHITE
  FIELD L3TIME    AT 9,5   LEN 5  PROT DIM    COLOR=TURQUOISE
  FIELD L3TYPE    AT 9,12  LEN 4  PROT BRIGHT COLOR=YELLOW
  FIELD L3TITLE   AT 9,18  LEN 30 PROT BRIGHT COLOR=WHITE
  FIELD L4TIME    AT 11,5  LEN 5  PROT DIM    COLOR=TURQUOISE
  FIELD L4TYPE    AT 11,12 LEN 4  PROT BRIGHT COLOR=YELLOW
  FIELD L4TITLE   AT 11,18 LEN 30 PROT BRIGHT COLOR=WHITE
  FIELD L5TIME    AT 13,5  LEN 5  PROT DIM    COLOR=TURQUOISE
  FIELD L5TYPE    AT 13,12 LEN 4  PROT BRIGHT COLOR=YELLOW
  FIELD L5TITLE   AT 13,18 LEN 30 PROT BRIGHT COLOR=WHITE
  FIELD MESSAGE   AT 17,5  LEN 60 PROT DIM    COLOR=YELLOW
  FIELD FOOTER    AT 23,2  LEN 70 PROT DIM    COLOR=BLUE
ENDMAP
